import AppKit
import CryptoKit

/// Shared plain-text clipboard (docs/PROTOCOL.md §5a, "Clipboard behavior").
///
/// Polls the general pasteboard every 0.5 s, but only while `KBP2Server.canSendClipboard`
/// (a session with a clipboard-capable peer is authenticated and sharing is on), and applies
/// text the PC sends. Main queue only, like KBP2Server. Never logs clipboard contents.
@MainActor
final class ClipboardSync {
    private static let pollInterval: TimeInterval = 0.5
    /// Content the source marks as confidential, transient or auto-generated is never sent.
    private static let excludedTypes: Set<NSPasteboard.PasteboardType> = [
        NSPasteboard.PasteboardType("org.nspasteboard.ConcealedType"),
        NSPasteboard.PasteboardType("org.nspasteboard.TransientType"),
        NSPasteboard.PasteboardType("org.nspasteboard.AutoGeneratedType"),
    ]

    private let server: KBP2Server
    private let pasteboard = NSPasteboard.general
    private var timer: Timer?
    private var lastChangeCount = 0
    /// SHA-256 of the last text sent or received in this session (echo suppression).
    private var lastDigest: SHA256.Digest?

    init(server: KBP2Server) {
        self.server = server
        server.onClipboardAvailabilityChanged = { [weak self] available in
            self?.availabilityChanged(available)
        }
        server.onClipboardText = { [weak self] utf8 in self?.apply(utf8) }
        availabilityChanged(server.canSendClipboard)
    }

    /// Stop polling and drop the server callbacks.
    func stop() {
        stopPolling()
        server.onClipboardAvailabilityChanged = nil
        server.onClipboardText = nil
    }

    private func availabilityChanged(_ available: Bool) {
        if available {
            guard timer == nil else { return }
            // A new session: don't push what's already on the clipboard; only later changes.
            lastChangeCount = pasteboard.changeCount
            lastDigest = nil
            let t = Timer(timeInterval: Self.pollInterval, repeats: true) { [weak self] _ in
                MainActor.assumeIsolated { self?.poll() }
            }
            t.tolerance = 0.1
            RunLoop.main.add(t, forMode: .common)
            timer = t
        } else {
            stopPolling()
        }
    }

    private func stopPolling() {
        timer?.invalidate()
        timer = nil
        lastDigest = nil
    }

    private func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        guard server.canSendClipboard else { return }

        if let types = pasteboard.types, types.contains(where: Self.excludedTypes.contains) { return }
        guard let text = pasteboard.string(forType: .string), !text.isEmpty else { return }
        let utf8 = Data(text.utf8)
        guard utf8.count <= KBP2.maxTransferBytes else { return }  // too big: not sent at all
        let digest = SHA256.hash(data: utf8)
        guard digest != lastDigest else { return }
        lastDigest = digest
        server.sendClipboardText(utf8)
    }

    /// Text from the PC (already checked: complete transfer, valid UTF-8, ≤ 1 MiB).
    private func apply(_ utf8: Data) {
        let digest = SHA256.hash(data: utf8)
        lastDigest = digest
        let text = String(decoding: utf8, as: UTF8.self)
        pasteboard.clearContents()
        pasteboard.setString(text, forType: .string)
        // Our own write isn't a local change to send back.
        lastChangeCount = pasteboard.changeCount
    }
}
